-- Late A/B Experiment feedback: variant change hypothesis, guardrail KPI result,
-- Sample size & MDE group, experiment_status as sole lifecycle (omit generic status).

update templates
set
  name = 'A/B Experiment',
  description = 'Hypothesis-driven experiment brief with ICE scoring, KPIs, variants, and decision',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem / Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"Link the Problem or Insight document in Properties → Origin, then summarize the evidence that motivates this test.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[What did we learn or observe that justifies running this experiment?]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem Statement"}]},{"type":"paragraph","content":[{"type":"text","text":"State the business or user symptom — not the solution.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[e.g. Trial-to-paid conversion is flat despite traffic growth.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How Might We"}]},{"type":"paragraph","content":[{"type":"text","text":"Frame the opportunity as a How Might We question before locking the change.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[How might we …?]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hypothesis"}]},{"type":"paragraph","content":[{"type":"text","text":"If we [change], then [primary metric] will [direction], because [behavioral mechanism]. Capture Product / Market / Audience / Surface in Properties → Targeting.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If we "},{"type":"text","text":"[change]","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"[primary metric]","marks":[{"type":"bold"}]},{"type":"text","text":" will "},{"type":"text","text":"[increase/decrease]","marks":[{"type":"bold"}]},{"type":"text","text":", because "},{"type":"text","text":"[underlying reasoning].","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rationale"}]},{"type":"paragraph","content":[{"type":"text","text":"Evidence, prior tests, or behavioral theory that supports the mechanism.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Why this change should move the metric.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Falsification"}]},{"type":"paragraph","content":[{"type":"text","text":"What result would prove the hypothesis wrong? Write this before you launch.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[We will reject the hypothesis if …]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decision Rule"}]},{"type":"paragraph","content":[{"type":"text","text":"Pre-commit Win / Lose / Inconclusive actions (and financial framing) before seeing results. Capture Result + Decision selects in Properties after the run.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Win — [action, e.g. roll out to 100%]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lose — [action, e.g. revert / do nothing]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inconclusive — [action, e.g. iterate or gather more evidence]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sample Size & MDE"}]},{"type":"paragraph","content":[{"type":"text","text":"Pre-commit power before launch: fill Properties → Sample size & MDE (MDE, sample size per variant, eligible traffic/day). Also set Launch date and Duration.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MDE: [smallest lift worth detecting — see Properties]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Planned duration: [days or weeks]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Variants"}]},{"type":"paragraph","content":[{"type":"text","text":"For each variant: what changes (text/UI), any mockup image, and the change hypothesis — why this treatment should beat Control on the psychological trigger.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Control — Experience: [current] — Change hypothesis: n/a (baseline)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Variant B — Experience: [what changes; attach image] — Change hypothesis: [why this triggers better than Control]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Risks & Dependencies"}]},{"type":"paragraph","content":[{"type":"text","text":"Material blockers only — eng capacity, analytics, legal, conflicting tests.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Risk or dependency]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Results: Insight, Learning & Decision"}]},{"type":"paragraph","content":[{"type":"text","text":"After the run: fill Primary / Secondary / Guardrail KPI result groups (a green primary with a broken guardrail is usually a no-rollout). Set Result + Decision in Properties. Lifecycle is Experiment status only — use that for Kanban.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Insight:]"}]},{"type":"paragraph","content":[{"type":"text","text":"[Learning:]"}]},{"type":"paragraph","content":[{"type":"text","text":"[Decision:]"}]}]}'::jsonb,
  metadata = '{"document_type":"ab_experiment","category":"product","use_cases":["A/B tests","Growth experiments","Feature rollout validation"],"supported_views":["kanban","dashboard","gantt"],"schema_fields":[{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"experiment_status","field_label":"Experiment status","field_type":"status","options":[{"value":"backlog","label":"Backlog","category":"unstarted"},{"value":"design","label":"Design","category":"unstarted"},{"value":"engineering","label":"Engineering","category":"started"},{"value":"live","label":"Live","category":"started"},{"value":"analyzing","label":"Analyzing","category":"started"},{"value":"concluded","label":"Concluded","category":"completed"}],"ai_fill_enabled":true},{"field_key":"launch_date","field_label":"Launch date","field_type":"date","ai_fill_enabled":true},{"field_key":"date_active","field_label":"Duration","field_type":"date_range","ai_fill_enabled":true},{"field_key":"target_sprint","field_label":"Target sprint/quarter","field_type":"text","ai_fill_enabled":false},{"field_key":"funnel_stage","field_label":"Funnel stage (AARRR)","field_type":"select","options":["acquisition","activation","retention","referral","revenue"],"ai_fill_enabled":true},{"field_key":"growth_loop","field_label":"Growth loop","field_type":"text","ai_fill_enabled":true},{"field_key":"psychological_layer","field_label":"Psychological layer","field_type":"text","ai_fill_enabled":true},{"field_key":"target_segment","field_label":"Target segment","field_type":"text","ai_fill_enabled":true},{"field_key":"cost_of_experimentation","field_label":"Cost of experimentation","field_type":"number","options":{"unit":"days"},"ai_fill_enabled":false},{"field_key":"experiment_result","field_label":"Result","field_type":"select","options":["winner","loser","stopped","inconclusive"],"ai_fill_enabled":false},{"field_key":"experiment_decision","field_label":"Decision","field_type":"select","options":["roll_out","do_nothing","iterate"],"ai_fill_enabled":false},{"field_key":"erosion_risk","field_label":"Long-term erosion tracking","field_type":"checkbox","ai_fill_enabled":false}],"schema_groups":[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"product","field_label":"Product","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true},{"sub_key":"surface","field_label":"Surface","field_type":"text","ai_fill_enabled":true},{"sub_key":"country","field_label":"Country","field_type":"text","ai_fill_enabled":true}]},{"group_key":"ice","group_label":"ICE","repeatable":false,"fields":[{"sub_key":"impact","field_label":"Impact (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"confidence","field_label":"Confidence (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"ease","field_label":"Ease / effort (1–10)","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi","group_label":"Primary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"secondary_kpi","group_label":"Secondary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"guardrail_kpi","group_label":"Guardrail KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"power","group_label":"Sample size & MDE","repeatable":false,"fields":[{"sub_key":"mde","field_label":"Minimum detectable effect","field_type":"text","ai_fill_enabled":true},{"sub_key":"sample_size","field_label":"Sample size (per variant)","field_type":"number","ai_fill_enabled":false},{"sub_key":"traffic_per_day","field_label":"Eligible traffic / day","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi_result","group_label":"Primary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"secondary_kpi_result","group_label":"Secondary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"guardrail_kpi_result","group_label":"Guardrail KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]}],"default_properties":{"experiment_status":"backlog","funnel_stage":"activation"}}'::jsonb
where slug = 'ab-experiment'
  and coalesce(is_system, false) = true
  and workspace_id is null;

-- Seed power + guardrail result (and full group set) onto workspaces with A/B fields.
do $migration$
declare
  ws record;
begin
  for ws in
    select distinct workspace_id
    from metadata_schemas
    where field_key in ('experiment_status', 'primary_kpi_label', 'guardrail_kpi_label')
  loop
    perform public.seed_scope_metadata_groups(
      ws.workspace_id,
      '[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"product","field_label":"Product","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true},{"sub_key":"surface","field_label":"Surface","field_type":"text","ai_fill_enabled":true},{"sub_key":"country","field_label":"Country","field_type":"text","ai_fill_enabled":true}]},{"group_key":"ice","group_label":"ICE","repeatable":false,"fields":[{"sub_key":"impact","field_label":"Impact (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"confidence","field_label":"Confidence (1–10)","field_type":"number","ai_fill_enabled":false},{"sub_key":"ease","field_label":"Ease / effort (1–10)","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi","group_label":"Primary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"secondary_kpi","group_label":"Secondary KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"guardrail_kpi","group_label":"Guardrail KPI","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":true},{"sub_key":"baseline","field_label":"Baseline","field_type":"text","ai_fill_enabled":true},{"sub_key":"target","field_label":"Target","field_type":"text","ai_fill_enabled":true}]},{"group_key":"power","group_label":"Sample size & MDE","repeatable":false,"fields":[{"sub_key":"mde","field_label":"Minimum detectable effect","field_type":"text","ai_fill_enabled":true},{"sub_key":"sample_size","field_label":"Sample size (per variant)","field_type":"number","ai_fill_enabled":false},{"sub_key":"traffic_per_day","field_label":"Eligible traffic / day","field_type":"number","ai_fill_enabled":false}]},{"group_key":"primary_kpi_result","group_label":"Primary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"secondary_kpi_result","group_label":"Secondary KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]},{"group_key":"guardrail_kpi_result","group_label":"Guardrail KPI result","repeatable":false,"fields":[{"sub_key":"label","field_label":"Label","field_type":"text","ai_fill_enabled":false},{"sub_key":"value","field_label":"Observed value","field_type":"text","ai_fill_enabled":false}]}]'::jsonb
    );
  end loop;
end;
$migration$;
